"use client";

import * as React from "react";
import { CircleOff, Clock } from "lucide-react";

type SpanProps = React.ComponentProps<"span">;

export type ExpiringBadgeTone = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5" | "muted";
export type ExpiringBadgePhase = "ok" | "warn" | "danger" | "expired";
export type ExpiringBadgeTime = Date | number | string;

export type ExpiringBadgeRemaining = {
  /** Milliseconds left, never negative. Infinity when the badge has no expiry. */
  ms: number;
  /** Clock parts of the time left (3 days, 2 hours, 13 minutes, 40 seconds). */
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
  /** Share of the span still left, 0..1. Null when there is no span (no startedAt and no duration) or no expiry. */
  fraction: number | null;
  expired: boolean;
};

export type ExpiringBadgeProps = SpanProps & {
  /** When the badge expires. Date, epoch ms or an ISO string. */
  expiresAt?: ExpiringBadgeTime;
  /** Where the rim counts from (100 %). Defaults to expiresAt − duration. */
  startedAt?: ExpiringBadgeTime;
  /** Length of the span in ms. Without expiresAt the span starts when the badge mounts (or at startedAt). */
  duration?: number;
  /** Static content or a function of the time left; live badges call it every second. */
  label: React.ReactNode | ((remaining: ExpiringBadgeRemaining) => React.ReactNode);
  /** Shown once the time is up. Default "Expired". */
  expiredLabel?: React.ReactNode;
  /** Rim and icon colour while healthy. Default "chart-1". */
  tone?: ExpiringBadgeTone;
  /** Share of the span at which the badge turns amber. Default 0.15. */
  warnAt?: number;
  /** Share of the span at which it turns red. Default 0.05. */
  dangerAt?: number;
  /** Re-render every second so a countdown label and the rim stay current. */
  live?: boolean;
  /** Leading 12 px icon. Defaults to a clock when the badge can expire; pass null for none. */
  icon?: React.ReactNode;
  /** Icon shown after expiry. Default a struck circle. */
  expiredIcon?: React.ReactNode;
  /** Draw the time rim. Default true (it needs startedAt or duration to know the span). */
  rim?: boolean;
  /** Hover/focus tooltip. Default "Expires <date>"; false hides it. */
  tooltip?: React.ReactNode | false;
  /** Used by the screen-reader announcement on expiry: "<name> expired". */
  name?: string;
  /** Locale for the default tooltip date. Default "en-US". */
  locale?: string;
  /** Fires once when the badge crosses from live to expired while mounted. */
  onExpire?: () => void;
  /** Clock source, for tests and fixed demos. Default Date.now. */
  now?: () => number;
  /** Time multiplier for demos and previews. Default 1. */
  speed?: number;
  /** Delay before the rim draws itself in on mount, in ms. */
  enterDelay?: number;
};

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;
const ENTER_MS = 360;
const MORPH_MS = 240;
const ROLL_MS = 360;
/** Below this much real time left the rim is redrawn every frame; above it the per-tick value is enough (the change per frame is sub-pixel). */
const FRAME_WINDOW_MS = 3 * MINUTE;
const RIM_INSET = -0.75;

const TONE_VAR: { [tone in ExpiringBadgeTone]: string } = {
  "chart-1": "var(--color-chart-1)",
  "chart-2": "var(--color-chart-2)",
  "chart-3": "var(--color-chart-3)",
  "chart-4": "var(--color-chart-4)",
  "chart-5": "var(--color-chart-5)",
  muted: "var(--color-muted-foreground)",
};

const COLOR_VAR: { [phase in ExpiringBadgePhase]: string } = {
  ok: "var(--eb-tone)",
  warn: "var(--eb-warn)",
  danger: "var(--color-destructive)",
  expired: "var(--color-muted-foreground)",
};

const SURFACE: { [phase in ExpiringBadgePhase]: string } = {
  ok: "var(--eb-surface)",
  warn: "color-mix(in oklch, var(--eb-warn) 9%, var(--eb-surface))",
  danger: "color-mix(in oklch, var(--color-destructive) 10%, var(--eb-surface))",
  expired: "var(--eb-expired-surface)",
};

const TEXT: { [phase in ExpiringBadgePhase]: string } = {
  ok: "var(--color-foreground)",
  warn: "var(--color-foreground)",
  danger: "color-mix(in oklab, var(--color-destructive) 80%, var(--color-foreground))",
  expired: "var(--color-muted-foreground)",
};

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const easeOutCubic = (x: number) => 1 - (1 - clamp01(x)) ** 3;
const isDigit = (char: string) => char >= "0" && char <= "9";
const plural = (count: number, unit: string) => `${count} ${unit}${count === 1 ? "" : "s"} left`;

function toMs(value: ExpiringBadgeTime | undefined): number | null {
  if (value === undefined) return null;
  const ms = value instanceof Date ? value.getTime() : typeof value === "number" ? value : new Date(value).getTime();
  return Number.isFinite(ms) ? ms : null;
}

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(() => (typeof window === "undefined" ? true : window.matchMedia("(prefers-reduced-motion: reduce)").matches));
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

/** Stadium outline centred `inset` px inside the box (negative = outside), starting at the top centre and running clockwise. */
export function rimPath(width: number, height: number, inset = RIM_INSET) {
  const x0 = inset;
  const y0 = inset;
  const x1 = width - inset;
  const y1 = height - inset;
  const r = Math.max(0.5, (y1 - y0) / 2);
  const cx = (x0 + x1) / 2;
  return `M ${cx} ${y0} H ${x1 - r} A ${r} ${r} 0 0 1 ${x1 - r} ${y1} H ${x0 + r} A ${r} ${r} 0 0 1 ${x0 + r} ${y0} Z`;
}

export function describeRemaining(ms: number, fraction: number | null, expired: boolean): ExpiringBadgeRemaining {
  if (!Number.isFinite(ms)) return { ms, days: Infinity, hours: Infinity, minutes: Infinity, seconds: Infinity, fraction, expired };
  const left = Math.max(0, ms);
  return {
    ms: left,
    days: Math.floor(left / DAY),
    hours: Math.floor(left / HOUR) % 24,
    minutes: Math.floor(left / MINUTE) % 60,
    seconds: Math.floor(left / SECOND) % 60,
    fraction,
    expired,
  };
}

/** "3 days left" · "5 hours left" · "12 minutes left" · "40 seconds left" · "Expired". */
export function formatRemaining(remaining: ExpiringBadgeRemaining): string {
  if (remaining.expired) return "Expired";
  if (!Number.isFinite(remaining.ms)) return "";
  const days = Math.floor(remaining.ms / DAY);
  if (days >= 1) return plural(days, "day");
  const hours = Math.floor(remaining.ms / HOUR);
  if (hours >= 1) return plural(hours, "hour");
  const minutes = Math.floor(remaining.ms / MINUTE);
  if (minutes >= 1) return plural(minutes, "minute");
  return plural(Math.ceil(remaining.ms / SECOND), "second");
}

function RollCell({ char, reduced }: { char: string; reduced: boolean }) {
  const [state, setState] = React.useState({ char, leaving: null as string | null, down: false, turn: 0 });
  const inRef = React.useRef(null as HTMLSpanElement | null);
  const outRef = React.useRef(null as HTMLSpanElement | null);
  const timer = React.useRef(0);

  // Derived during render (not in an effect) so the first commit already carries the new glyph and the parent measures the final width.
  if (char !== state.char) {
    const down = isDigit(char) && isDigit(state.char) ? Number(char) < Number(state.char) : false;
    setState({ char, leaving: reduced ? null : state.char, down, turn: state.turn + 1 });
  }

  React.useLayoutEffect(() => {
    if (state.leaving === null) return;
    const enterFrom = state.down ? -100 : 100;
    const exitTo = state.down ? 100 : -100;
    const incoming = inRef.current;
    const outgoing = outRef.current;
    if (incoming && typeof incoming.animate === "function") incoming.animate([{ transform: `translateY(${enterFrom}%)`, opacity: 0 }, { transform: "translateY(0)", opacity: 1 }], { duration: ROLL_MS, easing: EASE });
    if (outgoing && typeof outgoing.animate === "function") outgoing.animate([{ transform: "translateY(0)", opacity: 1 }, { transform: `translateY(${exitTo}%)`, opacity: 0 }], { duration: ROLL_MS, easing: EASE, fill: "forwards" });
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setState((current) => ({ ...current, leaving: null })), ROLL_MS + 40);
  }, [state.turn, state.leaving, state.down]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  return (
    <span data-cell data-rolling={state.leaving !== null ? "true" : undefined} className="relative inline-block overflow-hidden whitespace-pre">
      <span ref={inRef} data-cell-in className="inline-block">{state.char}</span>
      {state.leaving !== null && <span ref={outRef} data-cell-out aria-hidden="true" className="absolute inset-0">{state.leaving}</span>}
    </span>
  );
}

/** Text whose characters roll individually, so a countdown moves only its seconds and "Expires in 1s" → "Expired" rolls one letter. */
function RollText({ text, reduced }: { text: string; reduced: boolean }) {
  const chars = [...text];
  return (
    <span data-roll className="inline-flex whitespace-pre">
      {chars.map((char, index) => <RollCell key={index} char={char} reduced={reduced} />)}
    </span>
  );
}

export function ExpiringBadge({
  expiresAt,
  startedAt,
  duration,
  label,
  expiredLabel = "Expired",
  tone = "chart-1",
  warnAt = 0.15,
  dangerAt = 0.05,
  live = false,
  icon,
  expiredIcon,
  rim = true,
  tooltip,
  name,
  locale = "en-US",
  onExpire,
  now,
  speed = 1,
  enterDelay = 0,
  className = "",
  style,
  tabIndex = 0,
  onPointerEnter,
  onPointerLeave,
  onBlur,
  ref,
  ...rest
}: ExpiringBadgeProps) {
  const reduced = useReducedMotion();
  const baseId = React.useId();
  const tooltipId = `${baseId}-tooltip`;
  const nowRef = React.useRef(now);
  nowRef.current = now;
  const onExpireRef = React.useRef(onExpire);
  onExpireRef.current = onExpire;
  const anchor = React.useRef(null as number | null);

  /** The badge's clock: the injected/system time, stretched by `speed` around the first reading. */
  const clock = React.useCallback(() => {
    const real = nowRef.current ? nowRef.current() : Date.now();
    if (anchor.current === null) anchor.current = real;
    return speed === 1 ? real : anchor.current + (real - anchor.current) * speed;
  }, [speed]);

  const [t, setT] = React.useState(() => clock());
  const mountTime = anchor.current ?? t;

  const endInput = toMs(expiresAt);
  const startInput = toMs(startedAt);
  let end = endInput;
  let start = startInput;
  if (end === null && duration !== undefined) {
    if (start === null) start = mountTime;
    end = start + duration;
  }
  if (start === null && end !== null && duration !== undefined) start = end - duration;
  const total = end !== null && start !== null && end > start ? end - start : null;
  const expired = end !== null && t >= end;
  const msLeft = end === null ? Infinity : Math.max(0, end - t);
  const fraction = total !== null && end !== null ? clamp01((end - t) / total) : null;
  const hasRim = rim && total !== null;
  const phase: ExpiringBadgePhase = expired ? "expired" : fraction !== null && fraction <= dangerAt ? "danger" : fraction !== null && fraction <= warnAt ? "warn" : "ok";
  const remaining = describeRemaining(msLeft, fraction, expired);
  const content = expired ? expiredLabel : typeof label === "function" ? label(remaining) : label;
  const text = typeof content === "string" || typeof content === "number" ? String(content) : null;
  const labelKey = text ?? (expired ? "\u0000expired" : "\u0000node");
  const target = hasRim && fraction !== null && !expired ? 1 - fraction : 1;

  const rootRef = React.useRef(null as HTMLSpanElement | null);
  const bodyRef = React.useRef(null as HTMLSpanElement | null);
  const svgRef = React.useRef(null as SVGSVGElement | null);
  const trackRef = React.useRef(null as SVGPathElement | null);
  const progressRef = React.useRef(null as SVGPathElement | null);
  const frame = React.useRef(0);
  const tween = React.useRef(null as Animation | null);
  const widthMorph = React.useRef(null as Animation | null);
  const lastWidth = React.useRef(0);
  const span = React.useRef({ end, total, speed });
  span.current = { end, total, speed };
  const enter = React.useRef({ start: 0, end: 0 });
  const initialOffset = React.useRef(!reduced && hasRim ? 1 : target);
  const wasExpired = React.useRef(expired);
  const [hover, setHover] = React.useState(false);
  const [announcement, setAnnouncement] = React.useState("");

  // Re-read the clock when the host swaps the `now` function (tests advance time this way).
  React.useEffect(() => { setT(clock()); }, [now, clock]);

  // Schedule the next re-render exactly when something visible changes: a second boundary (live), the warn/danger thresholds, the expiry, or the next unit of the time left.
  React.useEffect(() => {
    if (end === null || expired) return;
    const current = clock();
    const left = end - current;
    if (left <= 0) { setT(current); return; }
    const events = [left];
    if (total !== null) {
      for (const at of [warnAt, dangerAt]) {
        const until = left - at * total;
        if (until > 0) events.push(until);
      }
    }
    if (live) events.push(left % SECOND || SECOND);
    else {
      const unit = left > DAY ? DAY : left > HOUR ? HOUR : MINUTE;
      events.push(left % unit || unit);
    }
    const delay = (Math.min(...events) + 1) / speed;
    const id = window.setTimeout(() => setT(clock()), Math.max(16, delay));
    return () => window.clearTimeout(id);
  }, [t, end, total, live, warnAt, dangerAt, speed, clock, expired]);

  React.useEffect(() => {
    if (expired && !wasExpired.current) {
      onExpireRef.current?.();
      setAnnouncement(`${name ?? (typeof label === "string" ? label : "Badge")} expired`);
    }
    if (!expired) setAnnouncement("");
    wasExpired.current = expired;
  }, [expired, name, label]);

  /** Fits the two outline paths to the badge box. Called from the resize observer so width morphs keep the rim snug. */
  const layout = React.useCallback(() => {
    const root = rootRef.current;
    const svg = svgRef.current;
    if (!root || !svg) return;
    const { width, height } = root.getBoundingClientRect();
    if (width === 0 || height === 0) return;
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
    const d = rimPath(width, height);
    trackRef.current?.setAttribute("d", d);
    progressRef.current?.setAttribute("d", d);
  }, []);

  React.useLayoutEffect(() => {
    layout();
    const root = rootRef.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(layout);
    observer.observe(root);
    return () => observer.disconnect();
  }, [layout, hasRim]);

  const writeOffset = (value: number) => {
    const path = progressRef.current;
    if (path) path.style.strokeDashoffset = String(value);
  };

  /** One writer for the rim: draws it in on mount, then follows the clock every frame while the end is near. Stops once nothing moves. */
  const runFrames = React.useCallback(() => {
    if (frame.current) return;
    const step = () => {
      const { end: endAt, total: span0, speed: rate } = span.current;
      const real = performance.now();
      const tNow = clock();
      const f = endAt !== null && span0 !== null ? clamp01((endAt - tNow) / span0) : 0;
      const entering = real < enter.current.end;
      const drawn = entering ? f * easeOutCubic((real - enter.current.start) / ENTER_MS) : f;
      writeOffset(1 - drawn);
      const near = endAt !== null && span0 !== null && tNow < endAt && (endAt - tNow) / rate <= FRAME_WINDOW_MS;
      if (entering || near) frame.current = requestAnimationFrame(step);
      else { frame.current = 0; writeOffset(1 - f); }
    };
    frame.current = requestAnimationFrame(step);
  }, [clock]);

  React.useLayoutEffect(() => {
    if (reduced || !hasRim) return;
    const begin = performance.now() + enterDelay;
    enter.current = { start: begin, end: begin + ENTER_MS };
    runFrames();
    return () => { if (frame.current) { cancelAnimationFrame(frame.current); frame.current = 0; } };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Per-tick value when no frame loop is running; large jumps (an injected clock moving) tween briefly.
  React.useLayoutEffect(() => {
    const path = progressRef.current;
    if (!path) return;
    const nearEnd = end !== null && total !== null && !expired && (end - t) / speed <= FRAME_WINDOW_MS;
    if (!reduced && nearEnd && hasRim) { runFrames(); return; }
    if (frame.current) return;
    const current = Number.parseFloat(path.style.strokeDashoffset || String(target));
    tween.current?.cancel();
    writeOffset(target);
    if (reduced || !Number.isFinite(current) || Math.abs(current - target) < 0.01 || typeof path.animate !== "function") return;
    tween.current = path.animate([{ strokeDashoffset: String(current) }, { strokeDashoffset: String(target) }], { duration: 380, easing: EASE });
  }, [target, t, end, total, speed, expired, reduced, hasRim, runFrames]);

  React.useEffect(() => () => { if (frame.current) cancelAnimationFrame(frame.current); tween.current?.cancel(); }, []);

  // Width morph: when the label changes width (10s → 9s, "Expires in 1s" → "Expired") the pill resizes over 240 ms instead of jumping.
  React.useLayoutEffect(() => {
    const body = bodyRef.current;
    if (!body) return;
    const previous = widthMorph.current;
    const midway = previous && previous.playState === "running" ? body.getBoundingClientRect().width : null;
    previous?.cancel();
    widthMorph.current = null;
    const next = body.getBoundingClientRect().width;
    const from = midway ?? lastWidth.current;
    lastWidth.current = next;
    if (!from || Math.abs(next - from) < 0.5 || reduced || typeof body.animate !== "function") return;
    widthMorph.current = body.animate([{ width: `${from}px` }, { width: `${next}px` }], { duration: MORPH_MS, easing: EASE });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [labelKey]);

  const dateText = React.useMemo(() => {
    if (end === null) return null;
    try {
      return new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).format(end);
    } catch {
      return new Date(end).toLocaleString();
    }
  }, [end, locale]);
  const tip = tooltip === false ? null : tooltip !== undefined ? tooltip : dateText === null ? null : `${expired ? "Expired" : "Expires"} ${dateText}`;
  const showIcon = icon !== null && (icon !== undefined || end !== null);

  return (
    <span
      {...rest}
      ref={(node) => {
        rootRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) (ref as { current: HTMLSpanElement | null }).current = node;
      }}
      data-slot="expiring-badge"
      data-phase={phase}
      data-expired={expired ? "true" : "false"}
      data-fraction={fraction === null ? undefined : fraction.toFixed(3)}
      data-rim={hasRim ? "true" : "false"}
      data-live={live ? "true" : undefined}
      data-ms={Number.isFinite(msLeft) ? Math.round(msLeft) : undefined}
      tabIndex={tabIndex}
      aria-describedby={tip !== null ? tooltipId : undefined}
      onPointerEnter={(event) => { onPointerEnter?.(event); setHover(true); }}
      onPointerLeave={(event) => { onPointerLeave?.(event); setHover(false); }}
      onBlur={(event) => { onBlur?.(event); setHover(false); }}
      style={{ ...style, "--eb-tone": TONE_VAR[tone], "--eb-color": COLOR_VAR[phase] } as React.CSSProperties}
      className={`group relative inline-flex shrink-0 rounded-full align-middle outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background [--eb-expired-surface:var(--color-muted)] [--eb-surface:var(--color-card)] [--eb-warn:var(--color-chart-5)] dark:[--eb-expired-surface:color-mix(in_oklch,var(--color-muted)_45%,var(--color-card))] dark:[--eb-surface:var(--color-muted)] dark:[--eb-warn:var(--color-chart-3)] ${className}`}
    >
      <span
        ref={bodyRef}
        data-body
        className="relative inline-flex h-7 items-center gap-1.5 overflow-hidden rounded-full px-2.5 text-xs font-medium leading-4 tabular-nums transition-[background-color,color] duration-300 motion-reduce:transition-none"
        style={{ backgroundColor: SURFACE[phase], color: TEXT[phase] }}
      >
        {showIcon && (
          <span data-icon aria-hidden="true" className="relative grid size-3 shrink-0 place-items-center transition-colors duration-300 motion-reduce:transition-none [&_svg]:size-3" style={{ color: "var(--eb-color)" }}>
            <span data-icon-live className={`col-start-1 row-start-1 flex transition-opacity duration-300 motion-reduce:transition-none ${expired ? "opacity-0" : "opacity-100"}`}>{icon ?? <Clock />}</span>
            <span data-icon-expired className={`col-start-1 row-start-1 flex transition-opacity duration-300 motion-reduce:transition-none ${expired ? "opacity-100" : "opacity-0"}`}>{expiredIcon ?? <CircleOff />}</span>
          </span>
        )}
        <span data-label className="inline-flex whitespace-nowrap">
          {text !== null ? <RollText text={text} reduced={reduced} /> : content}
        </span>
      </span>
      {hasRim && (
        <svg
          ref={svgRef}
          data-rim
          aria-hidden="true"
          preserveAspectRatio="none"
          className={`pointer-events-none absolute inset-0 size-full overflow-visible transition-opacity duration-300 motion-reduce:transition-none ${expired ? "opacity-0" : "opacity-100"}`}
        >
          <path ref={trackRef} data-rim-track pathLength={1} fill="none" stroke="var(--color-border)" strokeWidth={1.5} />
          <path
            ref={progressRef}
            data-rim-progress
            pathLength={1}
            fill="none"
            stroke="var(--eb-color)"
            strokeWidth={1.5}
            strokeDasharray="1 1"
            style={{ strokeDashoffset: initialOffset.current, transition: reduced ? "none" : "stroke 300ms" }}
          />
        </svg>
      )}
      {tip !== null && (
        <span
          id={tooltipId}
          role="tooltip"
          data-tooltip
          data-shown={hover ? "true" : "false"}
          className="pointer-events-none absolute bottom-full left-1/2 z-10 mb-2 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-[11px] font-medium leading-none text-background opacity-0 shadow-sm transition-opacity duration-150 motion-reduce:transition-none group-focus-visible:opacity-100 data-[shown=true]:opacity-100"
        >
          {tip}
        </span>
      )}
      <span role="status" aria-live="polite" data-announce className="sr-only">{announcement}</span>
    </span>
  );
}

export default ExpiringBadge;

